            if len(stack) < 2:
                raise StackUnderflowError
            a = stack.pop()
            b = stack.pop()
            if word == '+':
                stack.append(b + a)
            elif word == '-':
                stack.append(b - a)
            elif word == '*':
                stack.append(b * a)
            elif word == '/':
                stack.append(b // a)
        elif word == 'DUP':
            if not stack:
                raise StackUnderflowError
            stack.append(stack[-1])
        elif word == 'DROP':
            if not stack:
                raise StackUnderflowError
            stack.pop()
        elif word == 'SWAP':
            if len(stack) < 2:
                raise StackUnderflowError
            a = stack.pop()
            b = stack.pop()
            stack.append(a)
            stack.append(b)
        elif word == 'OVER':
            if len(stack) < 2:
                raise StackUnderflowError
            a = stack[-2]
            b = stack[-1]
            stack.append(a)
