from collections import deque

class RelativeDistance:
    def __init__(self, family_tree):
        self.family_tree = family_tree
        self.graph = self._build_graph()

    def _build_graph(self):
        graph = {}
        for parents, children in self.family_tree:
            for child in children:
                graph[child] = graph.get(child, set())
                for parent in parents:
                    graph[child].add(parent)
                    graph[parent] = graph.get(parent, set())
                    graph[parent].add(child)
        return graph

    def degree_of_separation(self, person_a, person_b):
        if person_a not in self.graph or person_b not in self.graph:
            return -1

        queue = deque()
        queue.append((person_a, 0))
        visited = set()
        visited.add(person_a)

        while queue:
            current_person, distance = queue.popleft()
            if current_person == person_b:
                return distance
            for neighbor in self.graph.get(current_person, set()):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, distance + 1))
        return -1
