            encoded_text.append(char)
    return ' '.join([encoded_text[i:i+5] for i in range(0, len(encoded_text), 5)])

def decode(ciphered_text, a, b):
    if not are_coprime(a, 26):
        raise ValueError("a and 26 are not coprime")
    decoded_text = []
    for char in ciphered_text.replace(" ", "").lower():
        if char.isalpha():
            i = ord(char) - ord('a')
            a_inv = modinv(a, 26)
            decoded_i = (a_inv * (i - b)) % 26
            decoded_text.append(chr(decoded_i + ord('a')))
        elif char.isdigit():
            decoded_text.append(char)
    return ''.join(decoded_text)

def are_coprime(x, y):
    return gcd(x, y) == 1

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def modinv(a, m):
    m0, x0, x1 = m, 0, 1
    if m == 1:
        return 0
    while a > 1:
        q = a // m
        m, a = a % m, m
        x0, x1 = x1 - q * x0, x0
    if x1 < 0:
        x1 += m0
    return x1
