from collections import Counter

def total(basket):
    if not basket:
        return 0

    book_counts = Counter(basket)
    total_cost = 0
    sorted_books = sorted(book_counts.items(), key=lambda x: -x[1])

    while True:
        remaining_books = []
        current_group = []

        for book, count in sorted_books:
            if count > 0:
                current_group.append(book)
                remaining_books.append((book, count - 1))

        if not current_group:
            break

        group_size = len(current_group)
        discount = 0
        if group_size == 2:
            discount = 0.05
        elif group_size == 3:
            discount = 0.10
        elif group_size == 4:
            discount = 0.20
        elif group_size == 5:
            discount = 0.25

        total_cost += group_size * 8 * (1 - discount)
        sorted_books = sorted(remaining_books, key=lambda x: -x[1])

    return total_cost
