def can_chain(dominoes):
    if not dominoes:
        return True

    def is_valid_chain(chain):
        if not chain:
            return False
        first = chain[0]
        last = chain[-1]
        return first[0] == last[1]

    def backtrack(current_chain, remaining_dominoes):
        if not remaining_dominoes:
            return is_valid_chain(current_chain)

        for i in range(len(remaining_dominoes)):
            domino = remaining_dominoes[i]
            new_remaining = remaining_dominoes[:i] + remaining_dominoes[i+1:]

            # Try both orientations of the domino
            for d in [domino, (domino[1], domino[0])]:
                if not current_chain:
                    if backtrack([d], new_remaining):
                        return True
                else:
                    if d[0] == current_chain[-1][1]:
                        if backtrack(current_chain + [d], new_remaining):
                            return True
                    elif d[1] == current_chain[-1][1]:
                        if backtrack(current_chain + [(d[1], d[0])], new_remaining):
                            return True
        return False

    return backtrack([], dominoes)
```

