class SgfTree:
    def __init__(self, properties=None, children=None):
        self.properties = properties or {}
        self.children = children or []

    def __eq__(self, other):
        if not isinstance(other, SgfTree):
            return False
        for key, value in self.properties.items():
            if key not in other.properties:
                return False
            if other.properties[key] != value:
                return False
        for key in other.properties.keys():
            if key not in self.properties:
                return False
        if len(self.children) != len(other.children):
            return False
        for child, other_child in zip(self.children, other.children):
            if child != other_child:
                return False
        return True

    def __ne__(self, other):
        return not self == other

def parse(input_string):
    def parse_properties(s):
        properties = {}
        i = 0
        while i < len(s):
            if s[i] == ';':
                break
            if s[i] == '[':
                key_end = s.find(']', i)
                if key_end == -1:
                    raise ValueError("Invalid SGF format: missing ']' for key")
                key = s[i+1:key_end]
                value_start = key_end + 1
                value_end = s.find(']', value_start)
                if value_end == -1:
                    raise ValueError("Invalid SGF format: missing ']' for value")
                value = s[value_start+1:value_end]
                if key in properties:
                    if isinstance(properties[key], list):
                        properties[key].append(value)
                    else:
                        properties[key] = [properties[key], value]
                else:
                    properties[key] = value
                i = value_end + 1
            else:
                i += 1
        return properties, s[i:]

    def parse_tree(s):
        if not s.startswith('('):
            raise ValueError("Invalid SGF format: tree must start with '('")
        s = s[1:]
        properties, s = parse_properties(s)
        children = []
        while s.startswith('('):
            child, s = parse_tree(s)
            children.append(child)
        if not s.startswith(')'):
            raise ValueError("Invalid SGF format: tree must end with ')'")
        return SgfTree(properties, children), s[1:]

    if not input_string.startswith('(') or not input_string.endswith(')'):
        raise ValueError("Invalid SGF format: input must be enclosed in '()'")
    tree, _ = parse_tree(input_string)
    return tree
```

